package com.bocsoft.sqleditor.history;
import com.bocsoft.sqleditor.auth.AuthContext;import com.bocsoft.sqleditor.config.SqlEditorProperties;import com.bocsoft.sqleditor.datasource.DataSourceService;import com.bocsoft.sqleditor.history.persistence.ExecutionHistoryMapper;import com.bocsoft.sqleditor.metadata.MetadataCursorCodec;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class HistoryQueryServiceTest {@Test void scopesHistoryToCurrentUserAndEscapesWildcards(){ExecutionHistoryMapper mapper=mock(ExecutionHistoryMapper.class);when(mapper.listOwned(anyString(),any(),any(),any(),any(),any(),any(),any(),anyInt())).thenReturn(Collections.emptyList());SqlEditorProperties p=new SqlEditorProperties();p.getCursor().setSigningKey(Base64.getEncoder().encodeToString(new byte[32]));HistoryQueryService service=new HistoryQueryService(mapper,new MetadataCursorCodec(new ObjectMapper(),p),mock(DataSourceService.class));AuthContext auth=new AuthContext("user-a","a","A","product","P",Instant.now().plusSeconds(60));service.list(auth,"%_",null,null,null,null,30,null);verify(mapper).listOwned(eq("user-a"),eq("%\\%\\_%"),isNull(),isNull(),isNull(),isNull(),isNull(),isNull(),eq(31));}}
